import {recipeRepository as repo} from './repository.js';
import {shell,icon,escapeHTML as e,formatAmount,toast,fatal} from './ui.js';
shell('');const params=new URLSearchParams(location.search);const id=params.get('id');let recipe,servings;
function renderIngredients(){document.querySelector('#serving-number').textContent=servings;document.querySelector('#minus-serving').disabled=servings<=1;document.querySelector('#plus-serving').disabled=servings>=100;const checks=[...document.querySelectorAll('.ingredient-check input')].map(i=>i.checked);document.querySelector('#ingredients-list').innerHTML=recipe.ingredients.map((i,n)=>`<label class="ingredient-check"><input type="checkbox" ${checks[n]?'checked':''}><span>${e(i.name)}</span><small>${i.amount?formatAmount(i.amount*servings/recipe.servings):''} ${e(i.unit||(!i.amount?'за смаком':''))}</small></label>`).join('');}
function favoriteButton(){const b=document.querySelector('#detail-favorite');b.classList.toggle('is-favorite',!!recipe.favorite);b.setAttribute('aria-pressed',!!recipe.favorite);b.innerHTML=icon('heart')+(recipe.favorite?'У вашому обраному':'Додати до обраного');}
try{recipe=repo.get(id);if(!recipe){document.querySelector('main').innerHTML=`<div class="empty"><h1>Цей рецепт ще не записаний</h1><p>Можливо, його видалено або він збережений в іншому браузері.</p><a href="index.html" class="button">До моєї колекції</a></div>`;}else{servings=recipe.servings;document.title=`${recipe.title} — Смак`;document.querySelector('main').innerHTML=`<div class="detail-top"><a href="index.html" class="back">← До моєї колекції</a><div class="detail-actions"><button class="text-button" id="print">Друкувати</button><a class="text-button" href="new.html?id=${encodeURIComponent(id)}">Редагувати ↗</a><button class="text-button" id="delete">${icon('trash')} Видалити</button></div></div><section class="detail-hero"><div class="detail-photo">${recipe.image?`<img src="${e(recipe.image)}" alt="${e(recipe.title)}">`:`<span class="food-placeholder">${icon('book')}</span>`}</div><div class="detail-info"><span class="eyebrow">${e(recipe.category)}</span><h1>${e(recipe.title)}</h1><p>${e(recipe.description)}</p><div class="detail-meta"><span>${icon('clock')} ${recipe.time} хвилин</span><span>${icon('users')} ${recipe.servings} порц.</span></div><button class="button" id="detail-favorite"></button>${recipe.demo?'<p class="demo-notice">Рецепт-приклад для натхнення. Ви можете змінити його під себе.</p>':''}</div></section><div class="detail-layout"><aside class="ingredients-panel"><h2>Що знадобиться</h2><div class="serving-control"><span>Кількість порцій</span><button id="minus-serving" aria-label="Зменшити кількість порцій">−</button><strong id="serving-number" aria-live="polite"></strong><button id="plus-serving" aria-label="Збільшити кількість порцій">+</button></div><div id="ingredients-list"></div><p class="ingredients-hint">Відмічайте інгредієнти, які вже підготували.</p></aside><section class="instructions"><span class="eyebrow">КРОК ЗА КРОКОМ</span><h2>Готуємо із задоволенням</h2>${recipe.steps.map((s,i)=>`<div class="instruction"><span>${String(i+1).padStart(2,'0')}</span><p>${e(s)}</p></div>`).join('')}${recipe.notes?`<aside class="recipe-notes"><h3>МАЛЕНЬКІ СЕКРЕТИ</h3><p>${e(recipe.notes)}</p></aside>`:''}</section></div>`;renderIngredients();favoriteButton();document.querySelector('#minus-serving').onclick=()=>{if(servings>1){servings--;renderIngredients();}};document.querySelector('#plus-serving').onclick=()=>{if(servings<100){servings++;renderIngredients();}};document.querySelector('#detail-favorite').onclick=()=>{try{recipe.favorite=repo.toggleFavorite(id);favoriteButton();}catch(err){toast(err.message,true);}};document.querySelector('#print').onclick=()=>window.print();const dialog=document.querySelector('#delete-dialog');document.querySelector('#delete').onclick=()=>dialog.showModal();document.querySelector('#cancel-delete').onclick=()=>dialog.close();document.querySelector('#confirm-delete').onclick=()=>{try{repo.remove(id);location.href='index.html';}catch(err){dialog.close();toast(err.message,true);}};if(params.has('saved')){toast('Рецепт збережено. Час готувати щось смачне!');history.replaceState(null,'',`recipe.html?id=${encodeURIComponent(id)}`);}}}catch(err){fatal(err);}
